//! Cargo-driven `ftfd.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is ftfd-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The C left, and its part of cmake's C rule; reactos-link adds what every C
    // compile shares from reactos-link/cflags/c.<arch>.flags (Linker::c_compiled).
    let c_sources: &[&str] = &["win32ss/drivers/font/ftfd/rust_varargs_shim.c"];
    let c_includes: &[&str] = &[
        "@build/win32ss/drivers/font/ftfd",
        "win32ss/drivers/font/ftfd",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/freetype/include",
    ];
    let c_flags: &[&str] = match arch.as_str() {
        "x86" => &["-std=gnu99", "@core"],
        "x86_64" => &["-std=gnu99", "-U_X86_", "-UWIN32", "@core"],
        "aarch64" => &["-std=gnu99", "@core"],
        _ => unreachable!(),
    };
    let c_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/win32ss/drivers/font/ftfd",
        "win32ss/drivers/font/ftfd",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_FtfdEnableDriver@12", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "FtfdEnableDriver", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "FtfdEnableDriver", 0x7ffb00000000u64),
        o => panic!("ftfd-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:freetype", "engine:c:libcntpr", "engine:c:setjmp", "engine:pseh", "import:win32k", "engine:cntpr_rust", "engine:chkstk"],
        "x86_64" => &["body", "engine:c:freetype", "engine:c:libcntpr", "engine:c:setjmp", "engine:pseh", "import:win32k", "engine:cntpr_rust"],
        "aarch64" => &["body", "engine:c:freetype", "engine:c:libcntpr", "engine:c:setjmp", "engine:pseh", "import:win32k", "engine:cntpr_rust", "engine:chkstk"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("ftfd-rust")
        .rust_user_target()
        .c_compiled("ftfd_shims", c_sources, c_includes, c_flags, c_defines)
        .rc("win32ss/drivers/font/ftfd/freetype.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("win32ss/drivers/font/ftfd/ftfd.spec", "ftfd.dll")
        .import_lib("win32ss/win32k.spec", "win32k.sys", "win32k")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
